import defProps from '../../libs/config/props'
import test from '../../libs/function/test'
import type { ExtractPropTypes, PropType } from 'vue'
import type { SuUni } from '../../types/uni'

export const avatarProps = {
  /** 头像图片路径(不能为相对路径) */
  src: {
    type: String,
    default: () => defProps.avatar.src
  },
  /** 
   * 头像形状，circle-圆形，square-方形
   * @enum {String} circle-圆形
   * @enum {String} square-方形
   * @default circle
   */
  shape: {
    type: String as PropType<SuUni.Shape>,
    default: () => defProps.avatar.shape
  },
  /** 
   * 头像尺寸
   * @default 40
   */
  size: {
    type: [String, Number] as PropType<SuUni.AvatarSize | number>,
    default: () => defProps.avatar.size
  },
  /** 
   * 裁剪模式
   * @description 头像图片的裁剪类型，与uni的image组件的mode参数一致，如效果达不到需求，可尝试传widthFix值 （默认 'scaleToFill' ）
   * @default scaleToFill
   */
  mode: {
    type: String as PropType<UniHelper.ImageMode>,
    default: () => defProps.avatar.mode
  },
  /** 显示的文字 */
  text: {
    type: String,
    default: () => defProps.avatar.text
  },
  /** 
   * 背景色
   * @default #c0c4cc
   */
  bgColor: {
    type: String,
    default: () => defProps.avatar.bgColor
  },
  /** 
   * 文字颜色
   * @default #ffffff
   */
  color: {
    type: String,
    default: () => defProps.avatar.color
  },
  /** 
   * 文字大小
   * @default 18
   */
  fontSize: {
    type: [String, Number],
    default: () => defProps.avatar.fontSize
  },
  /** 显示的图标 */
  icon: {
    type: String,
    default: () => defProps.avatar.icon
  },
  /** 
   * 显示小程序头像，只对百度，微信，QQ小程序有效
   * @default false
   */
  mpAvatar: {
    type: Boolean,
    default: () => defProps.avatar.mpAvatar
  },
  /** 
   * 是否使用随机背景色
   * @default false
   */
  randomBgColor: {
    type: Boolean,
    default: () => defProps.avatar.randomBgColor
  },
  /** 加载失败的默认头像(组件有内置默认图片) */
  defaultUrl: {
    type: String,
    default: () => defProps.avatar.defaultUrl
  },
  /** 如果配置了randomBgColor为true，且配置了此值，则从默认的背景色数组中取出对应索引的颜色值，取值0-19之间 */
  colorIndex: {
    type: [String, Number],
    // 校验参数规则，索引在0-19之间
    validator(n: number | string) {
      return test.range(+n, [0, 19]) || n === ''
    },
    default: () => defProps.avatar.colorIndex
  },
  /** 组件标识符 */
  name: {
    type: String,
    default: () => defProps.avatar.name
  }
}


export type SuAvaterProps = ExtractPropTypes<typeof avatarProps>

export const base64Avatar =
  'data:image/jpg;base64,'
